begin;
create or replace function public.complete_mpesa_checkout(p_checkout_id text,p_result_code integer,p_result_description text,p_receipt text,p_amount numeric,p_proof text) returns jsonb language plpgsql security definer set search_path='' as $$declare x public.mpesa_checkouts;c public.campaigns;policy jsonb;cw uuid;pw uuid;fee numeric(14,2);transfer uuid:=gen_random_uuid();expected text;secret text;begin select callback_secret into secret from public.mpesa_private_config where id=true;expected:=encode(extensions.hmac(p_checkout_id||':'||p_result_code||':'||coalesce(p_receipt,''),secret,'sha256'),'hex');if expected is null or expected='' or expected<>p_proof then raise exception 'INVALID_PROOF';end if;select * into x from public.mpesa_checkouts where checkout_request_id=p_checkout_id for update;if x.id is null then raise exception 'CHECKOUT_NOT_FOUND';end if;if x.status<>'PENDING' then return jsonb_build_object('duplicate',true);end if;select * into c from public.campaigns where id=x.campaign_id for update;if p_result_code<>0 then update public.mpesa_checkouts set status='FAILED',result_code=p_result_code,result_description=left(p_result_description,500),completed_at=now() where id=x.id;update public.campaigns set funding_status='NOT_FUNDED' where id=c.id;return jsonb_build_object('status','FAILED');end if;if p_amount<>x.expected_amount or coalesce(p_receipt,'')='' then raise exception 'PAYMENT_MISMATCH';end if;select value into policy from public.business_settings where key='finance_policy';insert into public.wallets(owner_type,campaign_id,wallet_type,currency)values('CAMPAIGN',c.id,'CAMPAIGN_BUDGET','KES')on conflict do nothing;select id into cw from public.wallets where campaign_id=c.id and wallet_type='CAMPAIGN_BUDGET';insert into public.wallets(owner_type,profile_id,wallet_type,currency)values('PROFILE',x.created_by,'OPERATING','KES')on conflict do nothing;select id into pw from public.wallets where profile_id=x.created_by and wallet_type='OPERATING' and currency='KES';fee=round((p_amount*(policy->>'platform_commission_bps')::integer)/10000,2);insert into public.ledger_transactions(wallet_id,transaction_type,direction,amount,currency,reference_type,reference_id,description,status,idempotency_key,posted_at,transfer_id,created_by,metadata)values(cw,'CAMPAIGN_FUNDING','CREDIT',p_amount,'KES','mpesa_checkout',x.id,'M-Pesa campaign funding','POSTED','mpesa:'||p_checkout_id||':funding',now(),transfer,x.created_by,jsonb_build_object('receipt',p_receipt)),(cw,'PLATFORM_COMMISSION','DEBIT',fee,'KES','mpesa_checkout',x.id,'Sauti platform fee','POSTED','mpesa:'||p_checkout_id||':fee-debit',now(),transfer,x.created_by,'{}'),(pw,'PLATFORM_COMMISSION','CREDIT',fee,'KES','mpesa_checkout',x.id,'Sauti platform fee','POSTED','mpesa:'||p_checkout_id||':fee-credit',now(),transfer,x.created_by,'{}');update public.mpesa_checkouts set status='COMPLETED',result_code=0,result_description=p_result_description,receipt_number=p_receipt,actual_amount=p_amount,completed_at=now() where id=x.id;update public.campaigns set funding_status='FUNDED' where id=c.id;insert into public.financial_events(event_type,entity_type,entity_id,actor_profile_id,idempotency_key,payload)values('campaign.funded','campaign',c.id,x.created_by,'mpesa-funded:'||p_checkout_id,jsonb_build_object('gross',p_amount,'receipt',p_receipt));return jsonb_build_object('status','COMPLETED');end$$;
revoke execute on function public.complete_mpesa_checkout(text,integer,text,text,numeric,text) from public,authenticated;grant execute on function public.complete_mpesa_checkout(text,integer,text,text,numeric,text) to anon;
commit;
